*1|//! Failure-mode tests for the artifact acceptance sequence counter and issuance path.
*2|//!
*3|//! These tests cover strict durability failures, batch commit failures,
*4|//! compiled-IR readback failures, invalid workflow digest rejection, and
*5|//! counter overflow at u64::MAX. They prove that the RMW (read-modify-write)
*6|//! sequence in artifact issuance preserves counter monotonicity and that
*7|//! failures do not corrupt the journal.
 8|
*9|use crate::admission::AcceptedArtifact;
*10|use crate::error::JournalError;
*11|use crate::FjallJournal;
*12|use vb_core::RuntimePolicy;
 13|
*14|// Parent module provides these private helpers for test use.
*15|use super::{minimal_workflow, temp_journal};
 16|
*17|/// Strict durability failure is precommit; counter must remain at 0.
*18|#[test]
*19|fn strict_persist_failure_is_precommit_counter_unchanged() -> Result<(), String> {
*20|    let journal = temp_journal().map_err(|e| format!("temp_journal: {e}"))?;
*21|    let workflow = minimal_workflow()?;
 22|
*23|    // Inject strict persist failure.
*24|    journal.fail_next_persist_for_test();
 25|
*26|    // Submission should fail with strict durability error.
*27|    let result = crate::admission::submit_artifact(&journal, &workflow, RuntimePolicy::Strict);
*28|    match result {
*29|        Err(JournalError::StrictDurabilityFailed) => {}
*30|        other => {
*31|            return Err(format!(
*32|                "expected StrictDurabilityFailed, got: {other:?}"
*33|            ));
*34|        }
*35|    }
 36|
*37|    // Counter must still be 0 — no artifact was issued.
*38|    match journal.artifact_acceptance.get(b"last_issued")? {
*39|        Some(_) => return Err("counter should be None after strict persist failure".to_string()),
*40|        None => {}
*41|    }
 42|
*43|    // Compiled IR keyspace must be empty.
*44|    let mut iter = journal.compiled_ir.iter();
*45|    let first = iter.next();
*46|    if first.is_some() {
*47|        return Err("compiled_ir should be empty after strict persist failure".to_string());
*48|    }
 49|
*50|    // Retry with same workflow; must succeed at seq 1.
*51|    let artifact = crate::admission::submit_artifact(&journal, &workflow, RuntimePolicy::Strict)
*52|        .map_err(|e| format!("retry submission failed: {e}"))?;
*53|    if artifact.accepted_at_seq.as_u64() != 1 {
*54|        return Err(format!(
*55|            "retry artifact should have seq 1, got {}",
*56|            artifact.accepted_at_seq.as_u64()
*57|        ));
*58|    }
 59|
*60|    Ok(())
*61|}
 62|
*63|/// Batch commit failure is precommit; counter and artifact keyspace must remain unchanged.
*64|#[test]
*65|fn batch_commit_failure_is_precommit_no_state_change() -> Result<(), String> {
*66|    let journal = temp_journal().map_err(|e| format!("temp_journal: {e}"))?;
*67|    let workflow = minimal_workflow()?;
 68|
*69|    // Inject batch commit failure.
*70|    journal.fail_next_batch_commit_for_test();
 71|
*72|    // Submission should fail with Fjall error.
*73|    let result = crate::admission::submit_artifact(&journal, &workflow, RuntimePolicy::Strict);
*74|    match result {
*75|        Err(JournalError::Fjall(_)) => {}
*76|        other => {
*77|            return Err(format!(
*78|                "expected Fjall error, got: {other:?}"
*79|            ));
*80|        }
*81|    }
 82|
*83|    // Counter must still be 0.
*84|    match journal.artifact_acceptance.get(b"last_issued")? {
*85|        Some(_) => return Err("counter should be None after batch commit failure".to_string()),
*86|        None => {}
*87|    }
 88|
*89|    // Artifact keyspace must be empty.
*90|    let mut iter = journal.compiled_ir.iter();
*91|    let first = iter.next();
*92|    if first.is_some() {
*93|        return Err("compiled_ir should be empty after batch commit failure".to_string());
*94|    }
 95|
*96|    // Retry succeeds at seq 1.
*97|    let artifact = crate::admission::submit_artifact(&journal, &workflow, RuntimePolicy::Strict)
*98|        .map_err(|e| format!("retry submission failed: {e}"))?;
*99|    if artifact.accepted_at_seq.as_u64() != 1 {
*100|        return Err(format!(
*101|            "retry artifact should have seq 1, got {}",
*102|            artifact.accepted_at_seq.as_u64()
*103|        ));
*104|    }
 105|
*106|    Ok(())
*107|}
 108|
*109|/// Compiled-IR readback failure occurs AFTER commit; counter advances and
*110|/// artifact record exists despite the error. This proves there is no all-Err
*111|/// rollback: the failure is detected after durable persistence.
*112|#[test]
*113|fn compiled_ir_readback_failure_is_postcommit_artifact_exists() -> Result<(), String> {
*114|    let journal = temp_journal().map_err(|e| format!("temp_journal: {e}"))?;
*115|    let workflow = minimal_workflow()?;
 116|
*117|    // Inject compiled IR readback failure.
*118|    journal.fail_next_compiled_ir_readback_for_test();
 119|
*120|    // Submission should fail with ArtifactMalformed (detected after commit).
*121|    let result = crate::admission::submit_artifact(&journal, &workflow, RuntimePolicy::Strict);
*122|    match result {
*123|        Err(JournalError::ArtifactMalformed) => {}
*124|        other => {
*125|            return Err(format!(
*126|                "expected ArtifactMalformed after readback failure, got: {other:?}"
*127|            ));
*128|        }
*129|    }
 130|
*131|    // Counter must be 1 (committed before readback check).
*132|    match journal.artifact_acceptance.get(b"last_issued")? {
*133|        Some(value) => {
*134|            if value.len() != 8 {
*135|                return Err(format!("counter value wrong length: {}", value.len()));
*136|            }
*137|            let bytes: [u8; 8] = value.try_into().map_err(|_| "counter slice try_into failed")?;
*138|            let counter = u64::from_be_bytes(bytes);
*139|            if counter != 1 {
*140|                return Err(format!(
*141|                    "counter should be 1 after postcommit readback failure, got {}",
*142|                    counter
*143|                ));
*144|            }
*145|        }
*146|        None => return Err("counter should be Some after postcommit readback failure".to_string()),
*147|    }
 148|
*149|    // Verify the compiled IR record actually exists by looking it up directly.
*150|    // We need the workflow digest to find it.
*151|    let workflow_parts = workflow.to_parts();
*152|    let serialized = postcard::to_allocvec(&workflow_parts)
*153|        .map_err(|e| format!("serialize workflow parts: {e}"))?;
*154|    let digest_bytes = blake3::hash(&serialized);
*155|    let expected_digest = vb_core::WorkflowDigest::from_bytes(digest_bytes.into());
 156|
*157|    // The journal's compiled_ir method should find it now (failure flag consumed).
*158|    let record = journal.compiled_ir(expected_digest)
*159|        .map_err(|e| format!("compiled_ir readback failed: {e}"))?;
*160|    match record {
*161|        Some(rec) => {
*162|            if rec.digest != expected_digest {
*163|                return Err("record digest does not match expected");
*164|            }
*165|        }
*166|        None => return Err("compiled IR record should exist after postcommit readback failure".to_string()),
*167|    }
 168|
*169|    // Follow-up valid submission at seq 2.
*170|    let artifact2 = crate::admission::submit_artifact(&journal, &workflow, RuntimePolicy::Strict)
*171|        .map_err(|e| format!("followup submission failed: {e}"))?;
*172|    if artifact2.accepted_at_seq.as_u64() != 2 {
*173|        return Err(format!(
*174|            "followup artifact should have seq 2, got {}",
*175|            artifact2.accepted_at_seq.as_u64()
*176|        ));
*177|    }
 178|
*179|    Ok(())
*180|}
