*183|/// mutation. This tests the checksum validation gate.
*184|#[test]
*185|fn invalid_workflow_canonical_digest_rejected_before_mutation() -> Result<(), String> {
*186|    let journal = temp_journal().map_err(|e| format!("temp_journal: {e}"))?;
 187|
*188|    // Build a valid workflow, then forge its digest to be wrong.
