*190|    use vb_core::workflow::{ResourceContract, WorkflowParts};
*191|    use vb_core::{CompiledNode, CompiledNodeKind, CompiledWorkflow, ConstIdx, SlotIdx, StepIdx, WorkflowDigest};
 192|
*193|    let mut parts = WorkflowParts {
*194|        semantic_source_identity: None,
*195|        name: Box::<str>::from("test_bad_digest"),
*196|        input_slots: Box::new([]),
*197|        digest: WorkflowDigest::from_bytes([0xFFu8; 32]), // intentionally wrong
