*211|                output: None,
*212|                next: None,
*213|                on_error: None,
*214|                error_slot: None,
*215|                kind: CompiledNodeKind::Finish {
*216|                    result: SlotIdx::new(0),
*217|                },
*218|            },
*219|        ]),
*220|        expressions: Box::new([]),
*221|        accessors: Box::new([]),
*222|        constants: Box::new([ConstValue::I64(42)]),
*223|        slot_count: 1,
*224|        symbols_count: 0,
*225|        entry: StepIdx::new(0),
*226|        resource_contract: ResourceContract::DEFAULT,
