                    .map(|artifact| {
                        let seq = artifact.accepted_at_seq.as_u64();
                        (seq, artifact.digest)
                    })
                    .map_err(|e| format!("submission failed: {e}"));

                let mut guard = r.lock().map_err(|e| format!("lock poisoned: {e}"))?;
                guard.push(result);
                Ok(())
            })
            .map_err(|e| format!("thread spawn failed: {e}"))?;

        handles.push(handle);
    }

